CREATE TABLE IF NOT EXISTS evidence_nonces (nonce TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_runs (environment TEXT NOT NULL, client_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_id TEXT NOT NULL, correlation_id TEXT NOT NULL, event_type TEXT NOT NULL, payload_hash TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, idempotency_key));
CREATE TABLE IF NOT EXISTS campaign_evidence (environment TEXT NOT NULL, client_id TEXT NOT NULL, evidence_id TEXT NOT NULL, correlation_id TEXT NOT NULL, source_url TEXT NOT NULL, source_type TEXT NOT NULL, geography TEXT NOT NULL, period TEXT NOT NULL, release_date TEXT NOT NULL, retrieved_at TEXT NOT NULL, methodology_version TEXT NOT NULL, source_hash TEXT NOT NULL, limitations_json TEXT NOT NULL, factual_approved INTEGER NOT NULL, rights_approved INTEGER NOT NULL, editorial_approved INTEGER NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, evidence_id));
CREATE TABLE IF NOT EXISTS content_draft_jobs (environment TEXT NOT NULL, client_id TEXT NOT NULL, evidence_id TEXT NOT NULL, correlation_id TEXT NOT NULL, job_type TEXT NOT NULL, status TEXT NOT NULL, llm_called INTEGER NOT NULL DEFAULT 0, content_publish_enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, evidence_id, job_type));
CREATE TABLE IF NOT EXISTS content_freshness_issues (environment TEXT NOT NULL, client_id TEXT NOT NULL, dedup_key TEXT NOT NULL, correlation_id TEXT NOT NULL, issue_type TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, dedup_key));
CREATE INDEX IF NOT EXISTS content_freshness_issues_open ON content_freshness_issues(environment, client_id, status);
